    authorizeConsoleDashboard: {
        parameters: {
            query?: never;
            header?: {
                /** @description The dashboard's host; a port is ignored. */
                "X-Forwarded-Host"?: string;
                /** @description The path and query the browser asked the dashboard for. */
                "X-Forwarded-Uri"?: string;
                /** @description The dashboard request's method; absent counts as GET. */
                "X-Forwarded-Method"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Let through. */
            200: {
                headers: {
                    /** @description The member's email. */
                    "X-Console-Email"?: string;
                    /** @description Admin or Viewer for Grafana, whose auth proxy reads its own role names; the member's role (admin, moderator) for the others. */
                    "X-Console-Role"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description No cookie for this dashboard. Location is the console's /dashboards/open?app=<app>&rd=<X-Forwarded-Uri>. */
            302: {
                headers: {
                    Location?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            401: components["responses"]["Unauthorized"];
            /** @description The member's role does not open this dashboard (console_forbidden), or DASHBOARD_HOSTS does not name the host (dashboard_host_unknown). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
    openConsoleDashboard: {
        parameters: {
            query: {
                ticket: string;
                /** @description Where to go on this host afterwards, a path such as /d/abc?from=now-1h. */
                rd?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Opened; Location is rd or /. */
            302: {
                headers: {
                    Location?: string;
                    "Set-Cookie"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            400: components["responses"]["BadRequest"];
            /** @description The ticket is unknown, used, expired, for another dashboard, or its console session has ended (invalid_dashboard_ticket). */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description DASHBOARD_HOSTS does not name this host (dashboard_host_unknown). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
